	return load.scan_groups[T](g.all()!)
}

// node_column_type returns the V type of a column of `nodes`.
fn node_column_type(column string) string {
	return match column {
		'id' { 'int' }
		'value' { 'int' }
		'next_id' { '?int' }
		else { '' }
	}
}

// order_by_next_value orders the rows by the `value` of their `next`.
pub fn (q NodeQuery) order_by_next_value() NodeQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."value" FROM "nodes" AS "t1" WHERE "t1"."id" = "t0"."next_id")'
	})
}

// order_by_next_value_desc orders the rows by the `value` of their
