// with_next loads each row's `next` (many_to_one `nodes`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q NodeQuery) with_next(configure ...fn (NodeQuery) NodeQuery) NodeQuery {
	mut next := q
	next.with_next = true
	next.next_fns = configure
	return next
}

// with_prev loads each row's `prev` (one_to_one `nodes`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q NodeQuery) with_prev(configure ...fn (NodeQuery) NodeQuery) NodeQuery {
	mut next := q
	next.with_prev = true
	next.prev_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q NodeQuery) all() ![]NodeNode {
	rows := load.select_where[models.Node](q.graph.client.conn, q.graph.client.prepare_query('nodes', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q NodeQuery) first() !NodeNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'nodes'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q NodeQuery) nodes(rows []models.Node) ![]NodeNode {
	mut nodes := rows.map(NodeNode{
		graph: q.graph
		node:  it
	})
	if q.with_next {
		found := q.load_next(rows, q.next_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.node.id.str()] or { [] }
			if list.len > 0 {
				node.next = &NodeNode{
					...list[0]
				}
			}
			node.loaded << 'next'
		}
	}
	if q.with_prev {
		found := q.load_prev(rows, q.prev_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.node.id.str()] or { [] }
			if list.len > 0 {
				node.prev = &NodeNode{
					...list[0]
				}
			}
			node.loaded << 'prev'
		}
	}
	return nodes
}

// load_next loads the `next` of `rows`, keyed by each row's key.
fn (q NodeQuery) load_next(rows []models.Node, fns []fn (NodeQuery) NodeQuery) !map[string][]NodeNode {
	mut sub := q.graph.nodes()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		if fk := row.next_id {
			keys << fk.str()
		}
	}
	targets := sub.nodes(load.select_in[models.Node](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_query('nodes', sub.query)!
	)!)!
	mut by_key := map[string]NodeNode{}
	for target in targets {
		by_key[target.node.id.str()] = target
	}
	mut found := map[string][]NodeNode{}
	for row in rows {
		fk := row.next_id or { continue }
		if target := by_key[fk.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// next_or_err returns the `next`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n NodeNode) next_or_err() !&NodeNode {
	if 'next' !in n.loaded {
		return NotLoadedError{
			edge: 'nodes.next'
		}
	}
	if target := n.next {
		return target
	}
	return NotFoundError{
		table: 'nodes'
	}
}

// load_prev loads the `prev` of `rows`, keyed by each row's key.
fn (q NodeQuery) load_prev(rows []models.Node, fns []fn (NodeQuery) NodeQuery) !map[string][]NodeNode {
	mut sub := q.graph.nodes()
	for configure in fns {
		sub = configure(sub)
	}
	children := sub.nodes(load.select_each[models.Node](q.graph.client.conn, 'next_id',
		rows.map(it.id.str()),
		query: q.graph.client.prepare_query('nodes', sub.query)!
	)!)!
	mut by_parent := map[string][]NodeNode{}
	for child in children {
		if parent := child.node.next_id {
			by_parent[parent.str()] << child
		}
	}
	return by_parent
}

// prev_or_err returns the `prev`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n NodeNode) prev_or_err() !&NodeNode {
	if 'prev' !in n.loaded {
		return NotLoadedError{
			edge: 'nodes.prev'
		}
	}
	if target := n.prev {
		return target
	}
	return NotFoundError{
		table: 'nodes'
	}
}

// query_next starts a query of this row's `next`, which matches
// nothing when the row has none.
pub fn (n NodeNode) query_next() NodeQuery {
	key := n.node.next_id or { return n.graph.nodes().where(load.in_ints('id', [])) }
	return n.graph.nodes().where(load.eq('id', key))
}

// query_prev starts a query of this row's `prev`.
pub fn (n NodeNode) query_prev() NodeQuery {
	return n.graph.nodes().where(load.eq('next_id', n.node.id))
}
